css:
/* wallpaper: pixel art, dusk tint, halftone dots */
[data-workspace-area="conversation"]{
  background-color:#16112a !important;
  background-image:
    radial-gradient(rgba(10,6,22,.5) 0.9px, transparent 1.3px),
    linear-gradient(180deg, rgba(14,16,42,.66) 0%, rgba(22,14,42,.74) 50%, rgba(16,8,20,.88) 100%),
    url(data:image/png;base64,) !important;
  background-size:3px 3px, 100% 100%, cover !important;
  background-position:0 0, 0 0, center 60% !important;
  background-repeat:repeat, no-repeat, no-repeat !important;
  image-rendering:pixelated;
}
.messages-timeline-scroll,[data-chat-composer-form]{background:transparent !important;}
[data-chat-header]{background:rgba(24,18,46,.55) !important;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid rgba(212,175,101,.14) !important;}

/* sidebar: dusk sky fading to a warm horizon glow */
[data-slot="sidebar-inner"]{
  background:
    radial-gradient(120% 40% at 50% 105%, rgba(224,138,50,.20), transparent 70%),
    linear-gradient(180deg,#141a3a 0%,#1a1636 45%,#221530 100%) !important;
  border-right:1px solid rgba(212,175,101,.12) !important;
}
[data-thread-item]{border-radius:8px;}
[data-thread-item]:hover{background:rgba(212,175,101,.07) !important;}
[data-thread-item][data-active="true"],[data-thread-item][aria-current="page"],[data-thread-item][data-selected="true"]{background:linear-gradient(90deg,rgba(224,138,50,.22),rgba(224,138,50,.04)) !important;box-shadow:inset 2px 0 0 #e8a246;}

/* frosted surfaces tinted like the mountains */
[data-slot="composer-host"]{background:rgba(36,26,62,.74) !important;border:1px solid rgba(212,175,101,.22) !important;backdrop-filter:blur(16px) saturate(1.3);-webkit-backdrop-filter:blur(16px) saturate(1.3);box-shadow:0 12px 36px rgba(12,6,24,.5),0 0 0 1px rgba(0,0,0,.15) !important;}
[data-slot="composer-host"]:focus-within{border-color:rgba(232,162,70,.7) !important;box-shadow:0 12px 36px rgba(12,6,24,.5),0 0 0 3px rgba(232,162,70,.15) !important;}
[data-user-message-bubble]{background:linear-gradient(135deg,rgba(72,44,104,.9),rgba(52,34,86,.9)) !important;border:1px solid rgba(212,175,101,.18) !important;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);}
[data-message-role="assistant"] .chat-markdown{color:#fbf5ea !important;text-shadow:0 1px 2px rgba(6,3,14,.9),0 0 10px rgba(12,6,26,.7);}
[data-timeline-row-kind]{text-shadow:0 1px 2px rgba(6,3,14,.85);}
.chat-markdown a{color:#f0b862 !important;}
.chat-markdown code:not(pre code){background:rgba(212,175,101,.14) !important;color:#f3cf8a !important;}
.chat-markdown-codeblock{background:rgba(16,12,30,.92) !important;border:1px solid rgba(212,175,101,.12) !important;}
[data-thread-details-card],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="dialog-popup"]{background:rgba(30,22,52,.88) !important;border:1px solid rgba(212,175,101,.16) !important;backdrop-filter:blur(18px) saturate(1.2);-webkit-backdrop-filter:blur(18px) saturate(1.2);}
[data-slot="tooltip-popup"]{background:#2a1f45 !important;color:#f6ecdb !important;border:1px solid rgba(212,175,101,.25) !important;}
[data-slot="input"],[data-slot="select-trigger"]{background:rgba(20,16,38,.6) !important;}
[data-slot="sidebar"] [data-slot="input"],[data-slot="sidebar"] input{background:transparent !important;border:0 !important;box-shadow:none !important;outline:none !important;}
[data-slot="sidebar"] input::placeholder{color:#a99cbf !important;}
[data-settings-page-scroll]{background:linear-gradient(180deg,#141a3a,#1d1533) !important;}

/* warm scrollbars */
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:rgba(212,175,101,.22);border-radius:10px;border:2px solid transparent;background-clip:padding-box;}
::-webkit-scrollbar-thumb:hover{background-color:rgba(232,162,70,.45);}
[data-slot="scroll-area-thumb"]{background:rgba(212,175,101,.3) !important;}
::selection{background:rgba(232,162,70,.45);color:#fff;}
